const recebido = $input.first().json ?? {};
const input = recebido.body && typeof recebido.body === 'object'
  ? recebido.body
  : recebido;

const action = String(
  input.action
  ?? input.acao_agendamento
  ?? ''
).trim().toUpperCase();

if (!['GERAR_OPCOES', 'AGENDAR'].includes(action)) {
  throw new Error(
    `action inválida: "${action}". Use GERAR_OPCOES ou AGENDAR.`
  );
}

const candidatoId = Number(
  input.candidato_id
  ?? input.id
);

if (!Number.isInteger(candidatoId) || candidatoId <= 0) {
  throw new Error(
    `candidato_id inválido: ${input.candidato_id ?? input.id}`
  );
}

const opcaoNumero = Number(
  input.opcao_numero
  ?? input.opcao_horario_escolhida
  ?? 0
);

if (action === 'AGENDAR' && ![1, 2, 3].includes(opcaoNumero)) {
  throw new Error(
    'Para AGENDAR, opcao_numero precisa ser 1, 2 ou 3.'
  );
}

return [{
  json: {
    action,
    candidato_id: candidatoId,
    opcao_numero: action === 'AGENDAR' ? opcaoNumero : null,
    calendar_id: String(
      input.calendar_id
      || 'ec7f0c6eb99778cac22b9a9aefec9e648e8ba5519172b6fc45ab03f938948c7f@group.calendar.google.com'
    ),
    timezone: String(
      input.timezone || 'America/Sao_Paulo'
    ),
    session: String(
      input.session || 'whats_junior'
    ),
    recrutadora_telefone: String(
      input.recrutadora_telefone || '5511951558547'
    ).replace(/\D/g, '')
  }
}];

const d = $input.first().json;
const data = new Intl.DateTimeFormat('pt-BR', {
  timeZone: d.timezone || 'America/Sao_Paulo',
  weekday: 'long',
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
}).format(new Date(d.entrevista_inicio));

return [{
  json: {
    ok: true,
    status: 'JA_AGENDADA',
    candidato_id: d.candidato_id,
    telefone: d.telefone,
    session: d.session,
    inicio: d.entrevista_inicio,
    fim: d.entrevista_fim,
    meet_link: d.entrevista_meet_link || '',
    google_event_url: d.entrevista_google_event_url || '',
    mensagem_whatsapp:
      `Sua entrevista já está agendada. ✅\n\n` +
      `📅 ${data}\n` +
      `💻 Google Meet\n` +
      `${d.entrevista_meet_link || d.entrevista_google_event_url || ''}\n\n` +
      `Entre no link com aproximadamente 5 minutos de antecedência.`
  }
}];

const d=$input.first().json;const now=new Date();const duration=Math.max(10,Number(d.entrevista_duracao_minutos||30));
const earliest=now.getTime()+60*60*1000;const days=Math.max(1,Math.min(60,Number(d.entrevista_busca_dias||7)));
return [{json:{...d,busca_inicio:new Date(earliest).toISOString(),busca_fim:new Date(now.getTime()+days*86400000).toISOString(),duracao_minutos:duration,motivo_regeneracao:d.motivo_regeneracao||''}}];

const base=$('Preparar janela de busca').first().json;const events=$input.all().map(i=>i.json).filter(Boolean);const tz=base.timezone||'America/Sao_Paulo';
const duration=Math.max(10,Number(base.duracao_minutos||30));const durMs=duration*60000;const startMin=new Date(base.busca_inicio).getTime(),endMax=new Date(base.busca_fim).getTime();
const days=(Array.isArray(base.entrevista_dias_semana)?base.entrevista_dias_semana:[1,2,3,4,5]).map(Number);
let hours=Array.isArray(base.entrevista_horarios)?base.entrevista_horarios:[];if(!hours.length)hours=['09:00','10:00','14:00','15:00'];
function dt(v){if(!v)return null;if(typeof v==='string')return new Date(v);return new Date(v.dateTime||`${v.date}T00:00:00-03:00`)}
const busy=events.filter(e=>String(e.status||'').toLowerCase()!=='cancelled'&&String(e.transparency||'').toLowerCase()!=='transparent').map(e=>[dt(e.start)?.getTime(),dt(e.end)?.getTime()]).filter(x=>x[0]&&x[1]);
const dateFmt=new Intl.DateTimeFormat('en-CA',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'});const weekFmt=new Intl.DateTimeFormat('en-US',{timeZone:tz,weekday:'short'});
const display=new Intl.DateTimeFormat('pt-BR',{timeZone:tz,weekday:'long',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const weekMap={Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6,Sun:7};
function offsetFor(date){const parts=new Intl.DateTimeFormat('en-US',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).formatToParts(date).reduce((a,p)=>(a[p.type]=p.value,a),{});const asUTC=Date.UTC(+parts.year,+parts.month-1,+parts.day,+parts.hour,+parts.minute,+parts.second);return asUTC-date.getTime()}
function localToUtc(dateStr,timeStr){const [y,m,d]=dateStr.split('-').map(Number),[hh,mm]=timeStr.split(':').map(Number);let guess=new Date(Date.UTC(y,m-1,d,hh,mm));return new Date(guess.getTime()-offsetFor(guess))}
const options=[];for(let cursor=startMin;cursor<endMax&&options.length<3;cursor+=86400000){const dateStr=dateFmt.format(new Date(cursor));const dow=weekMap[weekFmt.format(new Date(cursor))];if(!days.includes(dow))continue;for(const h of hours){const start=localToUtc(dateStr,h).getTime(),end=start+durMs;if(start<startMin||end>endMax)continue;if(busy.some(([s,e])=>start<e&&end>s))continue;options.push({opcao:options.length+1,inicio:new Date(start).toISOString(),fim:new Date(end).toISOString(),texto:display.format(new Date(start))});if(options.length===3)break}}
const prefix=base.motivo_regeneracao==='HORARIO_OCUPADO'?'O horário escolhido acabou de ser ocupado. Estas são novas opções disponíveis:\n\n':base.motivo_regeneracao==='OPCAO_INVALIDA'?'A opção não está mais disponível. Estas são novas opções:\n\n':'Você avançou para a entrevista on-line pelo Google Meet. Escolha um horário:\n\n';
const message=options.length?prefix+options.map(o=>`${o.opcao} — ${o.texto}`).join('\n')+`\n\nDuração aproximada: ${duration} minutos. Responda com o número da opção.`:'Sua triagem está aprovada, mas não há horários livres configurados no Google Calendar neste momento. A equipe foi avisada para liberar novas opções.';
return [{json:{...base,lote:`op-${base.candidato_id}-${Date.now()}`,opcoes:options,encontrou_tres:options.length>0,expira_em:new Date(Date.now()+24*3600000).toISOString(),mensagem_whatsapp:message}}];

const ev=$input.first().json;const d=$('Preparar evento da entrevista').first().json;const meet=ev.hangoutLink||ev.conferenceData?.entryPoints?.find(p=>p.entryPointType==='video')?.uri||'';const fmt=new Intl.DateTimeFormat('pt-BR',{timeZone:d.timezone||'America/Sao_Paulo',weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(d.inicio));const dur=Number(d.entrevista_duracao_minutos||30);
return [{json:{...d,google_event_id:ev.id||d.event_id,google_event_url:ev.htmlLink||'',meet_link:meet,mensagem_whatsapp:`Sua entrevista on-line foi agendada com sucesso! ✅

📅 ${fmt}
⏱️ Duração aproximada: ${dur} minutos
💻 Google Meet

Link para participar:
${meet||ev.htmlLink||''}

Entre no link com aproximadamente 5 minutos de antecedência.`,mensagem_recrutadora:`📌 Nova entrevista on-line agendada

Candidato(a): ${d.nome||'Não informado'}
WhatsApp: ${d.telefone||'Não informado'}
Vaga: ${d.vaga}
Data e horário: ${fmt}
Duração: ${dur} minutos

Google Meet:
${meet||ev.htmlLink||''}`}}];

const atual = $input.first().json ?? {};
let origem = atual;

function tentar(nome) {
  try {
    return $(nome).first().json ?? null;
  } catch {
    return null;
  }
}

const entrevista = tentar('Persistir entrevista');
const opcoes = tentar('Persistir opções e mensagem');
const existente = tentar('Retorno entrevista existente');
const carregado = tentar('Carregar candidato e vaga');

if (entrevista?.mensagem_whatsapp) {
  origem = entrevista;
} else if (opcoes?.mensagem_whatsapp) {
  origem = opcoes;
} else if (existente?.mensagem_whatsapp) {
  origem = existente;
}

return [{
  json: {
    ...origem,
    candidato_id: Number(
      origem.candidato_id
      ?? carregado?.candidato_id
    ),
    telefone: String(
      origem.telefone
      ?? carregado?.telefone
      ?? ''
    ).replace(/\D/g, ''),
    session: String(
      origem.session
      ?? carregado?.session
      ?? 'whats_junior'
    ),
    mensagem_whatsapp: String(
      origem.mensagem_whatsapp
      ?? origem.mensagem
      ?? ''
    ).trim()
  }
}];
